import { z } from "zod";
import catalog from "../../../../../contracts/readings/v1/readings.json";

// Generated by entitytypegen from Entity-type manifests and
// contracts/quantities/v1. It is the only source of reading-capable types and
// their displays.
const display = z.strictObject({
  name: z.string(), label: z.string(), scale: z.number().positive(), offset: z.number(), fraction_digits: z.number().int().min(0).max(3),
});
const reading = z.strictObject({
  kind: z.literal("quantity"), quantity: z.string(),
  unit: z.union([z.strictObject({ fixed: z.string().min(1) }), z.strictObject({ support_path: z.string().startsWith("/") })]),
  default_display: z.string(), displays: z.record(z.string(), display),
});
export type Reading = z.infer<typeof reading>;
export type ReadingDisplay = z.infer<typeof display>;

export const readings: Readonly<Record<string, Reading>> =
  z.strictObject({ $comment: z.string(), types: z.record(z.string(), reading) }).parse(catalog).types;

// Generation guarantees at least one reading type and one display each.
export const readingTypes = Object.keys(readings).sort() as [string, ...string[]];
export const displayKeys = [...new Set(Object.values(readings).flatMap(entry => Object.keys(entry.displays)))].sort() as [string, ...string[]];

export function acceptsDisplay(type: string, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(readings[type]?.displays ?? {}, key);
}

export function displayOptions(type: string): Array<{ key: string; name: string }> {
  return Object.entries(readings[type]?.displays ?? {}).sort(([left], [right]) => left.localeCompare(right)).map(([key, entry]) => ({ key, name: entry.name }));
}
